/*
 * 用于flash otp读
 * 参数buf 读取数据buffer
 * 参数len 读取长度
 * 参数zone_len 为otp单次读取长度
 * 返回值小于0 读取数据失败, 等于0 读取数据成功
 */
int norflash_read_otp(u8 *buf, const int len, const int zone_len);

