    norflash_write(NULL, buf, sizeof(buf), flash_exif_addr);

    puts("USER_FLASH_EXIF READ\r\n");
    memset(buf, 0, sizeof(buf));
    norflash_read(NULL, buf, sizeof(buf), flash_exif_addr);
    put_buf(buf, sizeof(buf));

    return 0;
}
