/// Upstream's `fm1_soc::machine::run_dual` (MIT), without the JIT switch,
/// running core 1 through `run_cpu1` below.
fn run_dual(
    cpu1: &mut Option<Cpu>,
    soc: &mut Soc,
    n: u32,
    ram_size: usize,
    mut run0: impl FnMut(&mut Soc, u32) -> Result<(), String>,
) -> Result<(), String> {
