        let c0 = soc.periph.cycles;
        if soc.core_paused(0) {
            soc.advance(k as u64);
        } else {
            run0(soc, k)?;
        }
        done += k;
        let dt = soc.periph.cycles - c0;
        run_cpu1(c1, soc, dt)?;
    }
    Ok(())
