/* SPDX-FileCopyrightText: 2026 japes98 */
/*
 * The flash chip on SPI0 (spiflash.rs), from code that runs in RAM: images
 * linked with image-ram.ld call ram_init() first. Everything a function
 * marked RAMCODE calls must be RAMCODE too (or inline), since fwtest ends
 * the run when code in the window runs while the chip is busy.
 */
#ifndef FLASH_H
#define FLASH_H

#include "board.h"

#define RAMCODE __attribute__((section(".ramtext"), noinline))
#define SPI0_CON REG(0x11c00u)

extern unsigned char __ramtext_load[], __ramtext_start[], __ramtext_end[];

static inline void ram_init(void)
{
    for (unsigned char *s = __ramtext_load, *d = __ramtext_start; d < __ramtext_end;)
        *(volatile unsigned char *)d++ = *s++;
}

static inline __attribute__((always_inline)) void fl_sel(void) { PD_OUT = 0; }
static inline __attribute__((always_inline)) void fl_desel(void) { PD_OUT = 1; }

static inline __attribute__((always_inline)) u32 fl_xfer(u32 b)
{
    SPI0_BUF = b;
    while (!(SPI0_CON & 0x8000u)) {
    }
    SPI0_CON |= 0x4000u;
    return SPI0_BUF & 0xffu;
}

static inline __attribute__((always_inline)) void fl_addr(u32 cmd, u32 a)
{
    fl_xfer(cmd);
    fl_xfer(a >> 16);
    fl_xfer(a >> 8);
    fl_xfer(a);
}

static inline __attribute__((always_inline)) u32 fl_status(void)
{
    fl_sel();
    fl_xfer(0x05u);
    SPI0_CON |= 0x1000u;
    u32 s = fl_xfer(0xffu);
    SPI0_CON &= ~0x1000u;
    fl_desel();
    return s;
}

static inline __attribute__((always_inline)) void fl_wren(void)
{
    fl_sel();
    fl_xfer(0x06u);
    fl_desel();
}

static inline __attribute__((always_inline)) void fl_wait(void)
{
    while (fl_status() & 1u) {
    }
}

#endif
EOF
cat > flashrw.c <<'EOF'
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* Copies 16 bytes from flash offset 0x5000 (read through the image window,
   which shows the chip from offset 0x4000, lib.rs XIP_FLASH_OFFSET) to
   OUTBUF, then, from RAM, erases the sector at 0x80000 and programs
   "flash written!!!" there over SPI0 (spiflash.rs), waiting for each to
   finish, then halts. */
#include "flash.h"

static RAMCODE void command(u32 op, u32 addr, const char *data, u32 n)
{
    fl_wren();
    fl_sel();
    fl_addr(op, addr);
    for (u32 i = 0; i < n; i++)
        fl_xfer((unsigned char)data[i]);
    fl_desel();
    fl_wait();
}

int main(void)
{
    ram_init();
    fl_desel();
    volatile unsigned char *xip = (volatile unsigned char *)(0x02000000u + 0x5000u - 0x4000u);
    for (u32 i = 0; i < 16; i++)
        OUTBUF[i] = xip[i];
    /* the bytes to program, in RAM: the window can't be read while busy */
    const char *text = "flash written!!!";
    for (u32 i = 0; i < 16; i++)
        OUTBUF[16 + i] = text[i];
    command(0x20, 0x80000, 0, 0);
    command(0x02, 0x80000, (const char *)&OUTBUF[16], 16);
    return 0;
}
EOF
