/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* From RAM, starts a 4 KiB erase at 0x80000 and returns to main in the
   window at once, without waiting: fwtest ends the run as a fault there.
   OUT(0) marks the return; it must never be written. */
#include "flash.h"

static RAMCODE void erase_and_go(void)
{
    fl_wren();
    fl_sel();
    fl_addr(0x20u, 0x80000u);
    fl_desel();
}

int main(void)
{
    ram_init();
    fl_desel();
    erase_and_go();
    OUT(0) = 0xbadu;
    return 0;
}
EOF
cat > flashload.c <<'EOF'
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* From RAM, starts a 4 KiB erase at 0x80000, then, still in RAM and while
   the chip is busy, reads a word of the image through the window: fwtest
   ends the run as a fault at that read. OUT(0) marks a run past it. */
#include "flash.h"

static RAMCODE void erase_and_read(void)
{
    fl_wren();
    fl_sel();
    fl_addr(0x20u, 0x80000u);
    fl_desel();
    OUT(1) = *(volatile u32 *)0x02000000u;
    fl_wait();
    OUT(0) = 0xbadu;
}

int main(void)
{
    ram_init();
    fl_desel();
    erase_and_read();
    return 0;
}
EOF
cat > flashirq.c <<'EOF'
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* Interrupts while the flash is busy. TIMER0 (prescaler setting 2, PRD
   1500: every 1 ms) raises source 4; its handler, in RAM, counts in OUT(1).
   From RAM with interrupts on: a 4 KiB erase at 0x80000, then a page
   program there, each waited for. OUT(2), OUT(3): TIMER4 ticks each took;
   OUT(4), OUT(5): the handler's count after each. Then the handler is
   moved to a copy in the window and another erase started: the next tick
   ends the run as a fault. OUT(0) marks the end of the first part. */
#include "flash.h"

#define TMR0_CON REG(0x10400u)
#define TMR0_CNT REG(0x10404u)
#define TMR0_PRD REG(0x10408u)

__attribute__((interrupt)) RAMCODE void tick_ram(void)
{
    OUT(1)++;
    TMR0_CON = 0x4021u;
}

__attribute__((interrupt)) void tick_window(void)
{
    OUT(6)++;
    TMR0_CON = 0x4021u;
}

static RAMCODE u32 timed(u32 op, u32 addr, u32 n)
{
    u32 t0 = T4_CNT;
    fl_wren();
    fl_sel();
    fl_addr(op, addr);
    for (u32 i = 0; i < n; i++)
        fl_xfer(0x5au);
    fl_desel();
    fl_wait();
    return T4_CNT - t0;
}

static RAMCODE void start_erase(void)
{
    fl_wren();
    fl_sel();
    fl_addr(0x20u, 0x81000u);
    fl_desel();
    fl_wait();
}

int main(void)
{
    ram_init();
    fl_desel();
    T4_CON = 1u;
    VECTOR(4) = (u32)tick_ram;
    TMR0_CNT = 0;
    TMR0_PRD = 1500u;
    TMR0_CON = 0x21u;
    ICFG(4) |= ICFG_ON(4, 1);
    __asm__ volatile("r0 = 0x100\n\ticfg = r0\n\tsti" ::: "r0");
    OUT(2) = timed(0x20u, 0x80000u, 0);
    OUT(4) = OUT(1);
    OUT(3) = timed(0x02u, 0x80000u, 16);
    OUT(5) = OUT(1);
    OUT(0) = 0x600du;
    VECTOR(4) = (u32)tick_window;
    start_erase();
    OUT(7) = 0xbadu;
    return 0;
}
EOF
cat > flashkeep.c <<'EOF'
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* A count kept in the flash across runs. From RAM: reads the word at chip
   offset 0x80000 into OUT(0) (0xFFFFFFFF on an erased chip). On an erased
   word it fills the sector at 0x80000 with zeros but for that word, which
   gets 1 (16 page programs); otherwise it erases the sector and does the
   same with the count plus one. OUT(1) marks the end. Run again with the
   last run's flash.bin as --flash; cut the power during the erase. */
#include "flash.h"

#define BUF ((volatile unsigned char *)0x01c01000u)

static RAMCODE u32 read_word(u32 a)
{
    u32 w = 0;
    fl_sel();
    fl_addr(0x03u, a);
    SPI0_CON |= 0x1000u;
    for (u32 i = 0; i < 4u; i++)
        w |= fl_xfer(0xffu) << (8u * i);
    SPI0_CON &= ~0x1000u;
    fl_desel();
    return w;
}

static RAMCODE void keep(u32 old)
{
    if (old != 0xffffffffu) {
        fl_wren();
        fl_sel();
        fl_addr(0x20u, 0x80000u);
        fl_desel();
        fl_wait();
    }
    for (u32 page = 0; page < 16u; page++) {
        fl_wren();
        fl_sel();
        fl_addr(0x02u, 0x80000u + 256u * page);
        for (u32 i = 0; i < 256u; i++)
            fl_xfer(BUF[256u * page + i]);
        fl_desel();
        fl_wait();
    }
}

int main(void)
{
    ram_init();
    fl_desel();
    u32 old = read_word(0x80000u);
    OUT(0) = old;
    u32 n = old == 0xffffffffu ? 1u : old + 1u;
    for (u32 i = 0; i < 4096u; i++)
        BUF[i] = 0;
    *(volatile u32 *)BUF = n;
    keep(old);
    OUT(1) = 0x600du;
    return 0;
}
EOF
