# Lists dual-issue pairs whose two halves write the same register, and
# what the following code does with that register (read first / written
# first / unknown), from toolchain disassembly files given as arguments.
import re, sys
LINE = re.compile(r'^\s*([0-9a-f]+):\s+((?:[0-9a-f]{2} )+)\s*\t+\s*(.*?)\s*$')
DEST = re.compile(r'^(r\d+)(?::(r\d+))?\s*(?:[-+*&|^]|<<|>>>|>>)?=(?!=)')
def dests(t):
    t = t.rstrip('#').strip()
    m = DEST.match(t)
    if m:
        return {g for g in m.groups() if g}
    m = re.match(r'^\{([^}]*)\}\s*=', t)
    if m:
        out = set()
        for part in m.group(1).split(','):
            part = part.strip()
            r = re.match(r'r(\d+)-r(\d+)', part)
            if r:
                a, b = int(r.group(1)), int(r.group(2))
                out |= {f'r{i}' for i in range(min(a, b), max(a, b) + 1)}
            elif re.match(r'r\d+$', part):
                out.add(part)
        return out
    return set()
def reads(t, reg):
    t = t.rstrip('#').strip()
    m = DEST.match(t)
    rhs = t[m.end():] if m else t
    if m and re.search(r'[-+*&|^<>]=', t[:m.end()]):
        rhs = t  # compound op reads its destination
    return re.search(r'\b' + reg + r'\b', rhs) is not None
hits = 0
for path in sys.argv[1:]:
    ins = []
    for l in open(path, errors='replace'):
        m = LINE.match(l)
        if m and m.group(3):
            ins.append((m.group(1), m.group(3)))
    for i in range(len(ins) - 1):
        a, b = ins[i][1], ins[i + 1][1]
        if not a.endswith('#'):
            continue
        both = dests(a) & dests(b)
        if not both:
            continue
        for reg in sorted(both):
            fate = 'end of listing'
            for j in range(i + 2, min(i + 40, len(ins))):
                t = ins[j][1]
                if reads(t, reg):
                    fate = f'read first: {t}'
                    break
                if reg in dests(t):
                    fate = f'written first: {t}'
                    break
                if re.match(r'^(goto|call|rts|rti|\{.*pc.*\}|if .* goto)', t.rstrip('#').strip()):
                    fate = f'flow: {t}'
                    break
            hits += 1
            print(f'{path.split("/")[-1]} {ins[i][0]}: [{a}] [{b}] {reg} -> {fate}')
print(f'{hits} pair(s) with both halves writing one register', file=sys.stderr)
