/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* A dual-issue pair whose two halves write the same register: the shape a
   flash driver has (spiflash.rs's SPI0, here a RAM stand-in so it runs
   anywhere). Each byte goes to a "BUF" word, then a done flag is polled,
   cleared, and BUF read back with the result unused; the compiler pairs
   that read with the next address's computation into the same register,
   and expects the computation's result after the pair (build.sh checks it
   still emits such a pair). OUT(4k)..OUT(4k+3) get what reached BUF for
   address 0x80000 + 256k, k = 0..3: 0x08, 0x00 + k, 0x00, 0x5A. */
#include "board.h"

#define FAKE_CON REG(0x01c01000u)
#define FAKE_BUF REG(0x01c01008u)

static u32 n;

static inline u32 xfer(u32 b)
{
    FAKE_BUF = b;
    OUT(n++) = FAKE_BUF;
    while (!(FAKE_CON & 0x8000u)) {
    }
    FAKE_CON |= 0x4000u;
    return FAKE_BUF & 0xffu;
}

static void page(u32 a)
{
    xfer(a >> 16);
    xfer(a >> 8);
    xfer(a);
    xfer(0x5au);
}

int main(void)
{
    FAKE_CON = 0x8000u;
    for (u32 k = 0; k < 4u; k++)
        page(0x80000u + 256u * k);
    return 0;
}
EOF
