/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* A dual-issue pair whose two halves write the same register, in the shape
   a flash driver has: over SPI0 (spiflash.rs), the read command (0x03) for
   the image's own bytes at chip offset 0x4000 + 256k, k = 0..3, one word
   each into OUT(k); the window's word at 0x02000000 + 256k into OUT(4 + k).
   The compiler pairs the unused read of BUF after the command byte with the
   next address's computation into the same register, and expects the
   computation's result after the pair (build.sh checks it still emits such
   a pair); then OUT(k) equals OUT(4 + k). */
#include "flash.h"

static void read_pages(void)
{
    for (u32 k = 0; k < 4u; k++) {
        fl_sel();
        fl_addr(0x03u, 0x4000u + 256u * k);
        SPI0_CON |= 0x1000u;
        u32 w = 0;
        for (u32 i = 0; i < 4u; i++)
            w |= fl_xfer(0xffu) << (8u * i);
        SPI0_CON &= ~0x1000u;
        fl_desel();
        OUT(k) = w;
    }
}

int main(void)
{
    fl_desel();
    read_pages();
    for (u32 k = 0; k < 4u; k++)
        OUT(4u + k) = REG(0x02000000u + 256u * k);
    return 0;
}
