fn alu4_fallback_keeps_pair_head() {
    // `94 f1 80 0c` r0 = r8 | (1 << r12) # (Rainbow's, then `[sp+16] = r0`): no table class
    // fits it, and the fallback ran it unpaired, so the store saw the new r0, not the old
