    let mut cpu = Cpu::new(0);
    cpu.regs[0] = 0x55;
    cpu.regs[8] = 0x100;
    cpu.regs[12] = 3;
    cpu.step(&mut ram).unwrap();
    let (_, after) = cpu.pair_pending.expect("a pair head");
    assert_eq!(cpu.regs[0], 0x55, "held back until the pair's second half");
    assert_eq!(after[0], 0x108);
}

